begin;
-- Additive Common 3.0 schema. Existing identities, Moments, and records remain intact.
alter table public.profiles add column avatar_path text,add column banner_path text,add column accent text not null default '#7954ff',add column social_links jsonb not null default '{}',add column layout text not null default 'grid',add column visibility text not null default 'public' check(visibility in('public','private'));
alter table public.user_settings add column messages_from text not null default 'following' check(messages_from in('anyone','following','connections','nobody'));
create table public.worlds(id uuid primary key default gen_random_uuid(),owner_id uuid not null references public.profiles on delete cascade,name text not null check(length(name)between 3 and 50),description text not null default '' check(length(description)<=1000),kind text not null check(kind in('personal','public')),visibility text not null check(visibility in('public','private')),category text not null,topics text[] not null default '{}' check(cardinality(topics)<=5),cover text not null default 'world-gaming',icon text not null default 'gamepad',content_mix jsonb not null default '{"video":30,"image":25,"text":25,"community":20}',contribution text not null default 'members' check(contribution in('anyone','members','approval','owner')),rules text not null default '' check(length(rules)<=2000),announcement text not null default '',created_at timestamptz not null default now(),check(kind<>'personal' or visibility='private'));
create table public.world_members(world_id uuid references public.worlds on delete cascade,user_id uuid references public.profiles on delete cascade,role text not null default 'member' check(role in('owner','moderator','member')),created_at timestamptz not null default now(),primary key(world_id,user_id));
create table public.world_preferences(world_id uuid references public.worlds on delete cascade,user_id uuid references public.profiles on delete cascade,sort text not null default 'balanced' check(sort in('balanced','newest','popular')),small_creators boolean not null default true,followed_communities boolean not null default false,content_mix jsonb,primary key(world_id,user_id));
create table public.communities(id uuid primary key default gen_random_uuid(),owner_id uuid not null references public.profiles on delete cascade,name text not null check(length(name)between 3 and 60),description text not null default '' check(length(description)<=1000),visibility text not null default 'public' check(visibility in('public','private')),approval_required boolean not null default false,announcement text not null default '',created_at timestamptz not null default now());
create table public.community_members(community_id uuid references public.communities on delete cascade,user_id uuid references public.profiles on delete cascade,role text not null default 'member' check(role in('owner','moderator','member')),status text not null default 'active' check(status in('pending','active')),created_at timestamptz not null default now(),primary key(community_id,user_id));
create table public.community_worlds(community_id uuid references public.communities on delete cascade,world_id uuid references public.worlds on delete cascade,primary key(community_id,world_id));
alter table public.moments add column community_id uuid references public.communities on delete set null,add column world_id uuid references public.worlds on delete set null;
create table public.posts(id uuid primary key default gen_random_uuid(),author_id uuid not null references public.profiles on delete cascade,type text not null check(type in('video','image','text','poll')),title text not null default '' check(length(title)<=150),body text not null default '' check(length(body)<=12000),topics text[] not null default '{}' check(cardinality(topics)<=5),visibility text not null default 'public' check(visibility in('public','followers','private')),community_id uuid references public.communities on delete set null,quoted_post_id uuid references public.posts on delete set null,pinned boolean not null default false,poll_options text[],poll_closes_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),deleted_at timestamptz);
create table public.post_worlds(post_id uuid references public.posts on delete cascade,world_id uuid references public.worlds on delete cascade,status text not null default 'published' check(status in('published','pending','removed')),submitted_by uuid not null references public.profiles on delete cascade,created_at timestamptz not null default now(),primary key(post_id,world_id));
create table public.user_follows(user_id uuid references public.profiles on delete cascade,target_id uuid references public.profiles on delete cascade,status text not null default 'active' check(status in('pending','active')),created_at timestamptz not null default now(),primary key(user_id,target_id),check(user_id<>target_id));
create table public.post_likes(post_id uuid references public.posts on delete cascade,user_id uuid references public.profiles on delete cascade,created_at timestamptz not null default now(),primary key(post_id,user_id));
create table public.post_saves(post_id uuid references public.posts on delete cascade,user_id uuid references public.profiles on delete cascade,created_at timestamptz not null default now(),primary key(post_id,user_id));
create table public.post_reposts(post_id uuid references public.posts on delete cascade,user_id uuid references public.profiles on delete cascade,created_at timestamptz not null default now(),primary key(post_id,user_id));
create table public.post_comments(id uuid primary key default gen_random_uuid(),post_id uuid not null references public.posts on delete cascade,author_id uuid not null references public.profiles on delete cascade,parent_id uuid references public.post_comments on delete cascade,body text not null check(length(body)between 1 and 3000),created_at timestamptz not null default now(),deleted_at timestamptz);
create table public.post_votes(post_id uuid references public.posts on delete cascade,user_id uuid references public.profiles on delete cascade,option_index integer not null check(option_index between 0 and 5),created_at timestamptz not null default now(),primary key(post_id,user_id));
create table public.post_impressions(post_id uuid references public.posts on delete cascade,user_id uuid references public.profiles on delete cascade,day date not null default current_date,watch_seconds numeric not null default 0 check(watch_seconds between 0 and 180),created_at timestamptz not null default now(),primary key(post_id,user_id,day));
create table public.post_shares(id uuid primary key default gen_random_uuid(),post_id uuid not null references public.posts on delete cascade,user_id uuid not null references public.profiles on delete cascade,created_at timestamptz not null default now());
create table public.profile_visits(profile_id uuid references public.profiles on delete cascade,user_id uuid references public.profiles on delete cascade,day date not null default current_date,primary key(profile_id,user_id,day));
create table public.uploaded_media(id uuid primary key default gen_random_uuid(),owner_id uuid not null references public.profiles on delete cascade,path text not null unique,mime text not null,size_bytes integer not null check(size_bytes between 1 and 104857600),kind text not null check(kind in('image','video')),status text not null default 'pending' check(status in('pending','ready','failed')),duration_seconds numeric,created_at timestamptz not null default now());
create table public.post_media(id uuid primary key default gen_random_uuid(),post_id uuid not null references public.posts on delete cascade,media_id uuid not null references public.uploaded_media on delete cascade,alt_text text not null default '' check(length(alt_text)<=500),position integer not null default 0,unique(post_id,position),unique(post_id,media_id));
create table public.conversations(id uuid primary key default gen_random_uuid(),creator_id uuid not null references public.profiles on delete cascade,title text not null default '',created_at timestamptz not null default now());
create table public.conversation_members(conversation_id uuid references public.conversations on delete cascade,user_id uuid references public.profiles on delete cascade,muted boolean not null default false,read_at timestamptz,primary key(conversation_id,user_id));
create table public.direct_messages(id uuid primary key default gen_random_uuid(),conversation_id uuid not null references public.conversations on delete cascade,author_id uuid not null references public.profiles on delete cascade,body text not null check(length(body)between 1 and 3000),created_at timestamptz not null default now(),edited_at timestamptz,deleted_at timestamptz);
create table public.moderation_actions(id uuid primary key default gen_random_uuid(),actor_id uuid references public.profiles on delete set null,world_id uuid references public.worlds on delete cascade,community_id uuid references public.communities on delete cascade,post_id uuid references public.posts on delete set null,action text not null,created_at timestamptz not null default now());
alter table public.notifications add column post_id uuid references public.posts on delete cascade,add column world_id uuid references public.worlds on delete cascade,add column conversation_id uuid references public.conversations on delete cascade,add column actor_id uuid references public.profiles on delete cascade;
alter table public.reports add column post_id uuid references public.posts on delete cascade,add column world_id uuid references public.worlds on delete cascade,add column comment_id uuid references public.post_comments on delete cascade;
create index on public.worlds(owner_id);create index on public.worlds(kind,visibility,created_at desc);create index on public.world_members(user_id);create index on public.world_preferences(user_id);
create index on public.communities(owner_id);create index on public.community_members(user_id);create index on public.community_worlds(world_id);
create index on public.posts(author_id,created_at desc,id desc);create index on public.posts(created_at desc,id desc)where deleted_at is null;create index on public.posts(community_id);create index on public.posts(quoted_post_id);create index on public.posts using gin(topics);
create index on public.post_worlds(world_id,status);create index on public.post_worlds(submitted_by);create index on public.user_follows(target_id,status);create index on public.post_likes(user_id);create index on public.post_saves(user_id);create index on public.post_reposts(user_id);create index on public.post_comments(post_id,created_at);create index on public.post_comments(author_id);create index on public.post_comments(parent_id);create index on public.post_votes(user_id);create index on public.post_impressions(user_id);create index on public.post_shares(post_id,created_at);create index on public.post_shares(user_id);create index on public.profile_visits(user_id);create index on public.uploaded_media(owner_id,created_at);create index on public.post_media(media_id);create index on public.moments(community_id);create index on public.moments(world_id);create index on public.conversations(creator_id);create index on public.conversation_members(user_id);create index on public.direct_messages(conversation_id,created_at);create index on public.direct_messages(author_id);create index on public.moderation_actions(actor_id);create index on public.moderation_actions(world_id);create index on public.moderation_actions(community_id);create index on public.moderation_actions(post_id);create index on public.notifications(post_id);create index on public.notifications(world_id);create index on public.notifications(conversation_id);create index on public.notifications(actor_id);create index on public.reports(post_id);create index on public.reports(world_id);create index on public.reports(comment_id);
create function private.world_visible(wid uuid)returns boolean language sql stable security definer set search_path='' as $$select exists(select 1 from public.worlds w where id=wid and not private.blocked(auth.uid(),w.owner_id)and(w.owner_id=auth.uid()or(w.kind='public'and(w.visibility='public'or exists(select 1 from public.world_members where world_id=wid and user_id=auth.uid())))))$$;
create function private.world_manager(wid uuid)returns boolean language sql stable security definer set search_path='' as $$select auth.uid()is not null and exists(select 1 from public.world_members where world_id=wid and user_id=auth.uid()and role in('owner','moderator'))$$;
create function private.community_visible(cid uuid)returns boolean language sql stable security definer set search_path='' as $$select exists(select 1 from public.communities c where id=cid and not private.blocked(auth.uid(),c.owner_id)and(c.visibility='public'or c.owner_id=auth.uid()or exists(select 1 from public.community_members where community_id=cid and user_id=auth.uid()and status='active')))$$;
create function private.community_manager(cid uuid)returns boolean language sql stable security definer set search_path='' as $$select auth.uid()is not null and exists(select 1 from public.community_members where community_id=cid and user_id=auth.uid()and status='active'and role in('owner','moderator'))$$;
create function private.post_visible(pid uuid)returns boolean language sql stable security definer set search_path='' as $$select exists(select 1 from public.posts p join public.profiles a on a.id=p.author_id where p.id=pid and p.deleted_at is null and not private.blocked(auth.uid(),p.author_id)and(p.author_id=auth.uid()or((a.visibility='public'or exists(select 1 from public.user_follows f where f.user_id=auth.uid()and f.target_id=p.author_id and f.status='active'))and(p.visibility='public'or(p.visibility='followers'and exists(select 1 from public.user_follows f where f.user_id=auth.uid()and f.target_id=p.author_id and f.status='active')))))and(p.community_id is null or private.community_visible(p.community_id)))$$;
create function private.conversation_member(cid uuid)returns boolean language sql stable security definer set search_path='' as $$select auth.uid()is not null and exists(select 1 from public.conversation_members where conversation_id=cid and user_id=auth.uid())and not exists(select 1 from public.conversation_members where conversation_id=cid and private.blocked(auth.uid(),user_id))$$;
create function private.media_visible(mid uuid)returns boolean language sql stable security definer set search_path='' as $$select exists(select 1 from public.uploaded_media m where id=mid and(m.owner_id=auth.uid()or(m.status='ready'and exists(select 1 from public.post_media pm where pm.media_id=mid and private.post_visible(pm.post_id)))))$$;
revoke all on function private.world_visible(uuid),private.world_manager(uuid),private.community_visible(uuid),private.community_manager(uuid),private.post_visible(uuid),private.conversation_member(uuid),private.media_visible(uuid)from public;
grant usage on schema private to anon;
grant execute on function private.world_visible(uuid),private.community_visible(uuid),private.post_visible(uuid),private.media_visible(uuid),private.blocked(uuid,uuid)to anon,authenticated;
grant execute on function private.world_manager(uuid),private.community_manager(uuid),private.conversation_member(uuid)to authenticated;
do $$declare t text;begin foreach t in array array['worlds','world_members','world_preferences','communities','community_members','community_worlds','posts','post_worlds','user_follows','post_likes','post_saves','post_reposts','post_comments','post_votes','post_impressions','post_shares','profile_visits','uploaded_media','post_media','conversations','conversation_members','direct_messages','moderation_actions']loop execute format('alter table public.%I enable row level security',t);execute format('revoke all on public.%I from anon,authenticated',t);execute format('grant select on public.%I to authenticated',t);end loop;end$$;
grant select on public.worlds,public.world_members,public.communities,public.community_members,public.community_worlds,public.posts,public.post_worlds,public.post_comments,public.post_media,public.uploaded_media,public.profiles to anon;
create policy public_profile on public.profiles for select to anon using(visibility='public');
create policy world_read on public.worlds for select to anon,authenticated using(private.world_visible(id));
create policy world_members_read on public.world_members for select to anon,authenticated using(private.world_visible(world_id)and not private.blocked((select auth.uid()),user_id));
create policy world_preferences_read on public.world_preferences for select to authenticated using(user_id=(select auth.uid()));
create policy community_read on public.communities for select to anon,authenticated using(private.community_visible(id));
create policy community_members_read on public.community_members for select to anon,authenticated using((private.community_visible(community_id)and status='active')or user_id=(select auth.uid())or private.community_manager(community_id));
create policy community_world_read on public.community_worlds for select to anon,authenticated using(private.community_visible(community_id)and private.world_visible(world_id));
create policy post_read on public.posts for select to anon,authenticated using(private.post_visible(id));
create policy post_world_read on public.post_worlds for select to anon,authenticated using(private.world_visible(world_id)and private.post_visible(post_id)and(status='published'or submitted_by=(select auth.uid())or private.world_manager(world_id)));
create policy follows_read on public.user_follows for select to authenticated using((status='active'or user_id=(select auth.uid())or target_id=(select auth.uid()))and not private.blocked((select auth.uid()),user_id)and not private.blocked((select auth.uid()),target_id));
create policy likes_read on public.post_likes for select to authenticated using(private.post_visible(post_id));
create policy saves_read on public.post_saves for select to authenticated using(user_id=(select auth.uid())and private.post_visible(post_id));
create policy reposts_read on public.post_reposts for select to authenticated using(private.post_visible(post_id));
create policy comment_read on public.post_comments for select to anon,authenticated using(private.post_visible(post_id)and not private.blocked((select auth.uid()),author_id));
create policy votes_read on public.post_votes for select to authenticated using(user_id=(select auth.uid())and private.post_visible(post_id));
create policy impressions_read on public.post_impressions for select to authenticated using(user_id=(select auth.uid()));
create policy shares_read on public.post_shares for select to authenticated using(user_id=(select auth.uid()));
create policy visits_read on public.profile_visits for select to authenticated using(user_id=(select auth.uid()));
create policy media_read on public.uploaded_media for select to anon,authenticated using(private.media_visible(id));
create policy post_media_read on public.post_media for select to anon,authenticated using(private.post_visible(post_id));
create policy conversation_read on public.conversations for select to authenticated using(private.conversation_member(id));
create policy conversation_members_read on public.conversation_members for select to authenticated using(private.conversation_member(conversation_id));
create policy dm_read on public.direct_messages for select to authenticated using(private.conversation_member(conversation_id));
create policy moderation_read on public.moderation_actions for select to authenticated using(private.world_manager(world_id)or private.community_manager(community_id));
grant update(avatar_path,banner_path,accent,social_links,layout,visibility)on public.profiles to authenticated;
grant update(messages_from)on public.user_settings to authenticated;
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types)values('social-media','social-media',false,104857600,array['image/png','image/jpeg','image/webp','video/mp4'])on conflict(id)do nothing;
create policy social_media_upload on storage.objects for insert to authenticated with check(bucket_id='social-media'and(storage.foldername(name))[1]=(select auth.uid())::text and exists(select 1 from public.uploaded_media m where m.path=name and m.owner_id=(select auth.uid())and m.status='pending'));
create policy social_media_read on storage.objects for select to anon,authenticated using(bucket_id='social-media'and exists(select 1 from public.uploaded_media m where m.path=name and private.media_visible(m.id)));
create policy social_media_delete on storage.objects for delete to authenticated using(bucket_id='social-media'and(storage.foldername(name))[1]=(select auth.uid())::text);
alter publication supabase_realtime add table public.posts,public.post_comments,public.direct_messages;
commit;
